grid=[[8]*22 for _ in range(22)]
pat=[[0,6,6],[6,6,6],[0,6,0],[6,6,6]]
placements=[(0,12,6),(5,0,6),(5,4,6),(5,8,4),(5,12,6),(10,0,6)]
for r,c,col in placements:
    for i,row in enumerate(pat):
        for j,v in enumerate(row):
            if v: grid[r+i][c+j]=col
print('\n'.join(' '.join(map(str,row)) for row in grid))

